mapper.select:
	SELECT DISTINCT sc.*,
		my_acc.access_type AS accessType,
       (
           SELECT u.user_name
           FROM search_condition_access o
           INNER JOIN users u ON o.user_no = u.user_no
           WHERE o.search_condition_no = sc.search_condition_no
             AND o.access_type = 'owner'
             AND ROWNUM = 1
       ) AS ownerName,
       (
           SELECT LISTAGG(u.user_name, ', ') WITHIN GROUP (ORDER BY u.user_name)
           FROM search_condition_access v
           INNER JOIN users u ON v.user_no = u.user_no
           WHERE v.search_condition_no = sc.search_condition_no
             AND v.access_type = 'viewer'
       ) AS viewerNames
	FROM search_condition sc
	INNER JOIN search_condition_access my_acc
		ON sc.search_condition_no = my_acc.search_condition_no

		my_acc.user_no = #{currentUserNo}



			AND sc.search_condition_title LIKE '%' || #{searchKeyWord} || '%'





				AND EXISTS (
					SELECT 1 FROM sc_detail_space d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.space_key = #{searchSpaceKey}
				)


				AND NOT EXISTS (
					SELECT 1 FROM sc_detail_space d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.space_key = #{searchSpaceKey}
				)






				AND EXISTS (
					SELECT 1 FROM sc_detail_worker d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.worker_no = #{searchWorkerNo}
				)


				AND NOT EXISTS (
					SELECT 1 FROM sc_detail_worker d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.worker_no = #{searchWorkerNo}
				)






				AND EXISTS (
					SELECT 1 FROM sc_detail_creator d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.creator_no = #{searchCreatorNo}
				)


				AND NOT EXISTS (
					SELECT 1 FROM sc_detail_creator d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.creator_no = #{searchCreatorNo}
				)





				AND EXISTS (
					SELECT 1
					FROM search_condition_access owner_acc
					WHERE owner_acc.search_condition_no = sc.search_condition_no
					AND owner_acc.access_type = 'owner'
					AND owner_acc.user_no = #{searchUserNo}
				)


				AND NOT EXISTS (
					SELECT 1
					FROM search_condition_access owner_acc
					WHERE owner_acc.search_condition_no = sc.search_condition_no
					AND owner_acc.access_type = 'owner'
					AND owner_acc.user_no = #{searchUserNo}
				)





				AND EXISTS (
					SELECT 1 FROM sc_detail_priority d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.priority = #{searchPriority}
				)


				AND NOT EXISTS (
					SELECT 1 FROM sc_detail_priority d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.priority = #{searchPriority}
				)






				AND EXISTS (
					SELECT 1 FROM sc_detail_status d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.status_no = #{searchStatusNo}
				)


				AND NOT EXISTS (
					SELECT 1 FROM sc_detail_status d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.status_no = #{searchStatusNo}
				)






				AND EXISTS (
					SELECT 1 FROM sc_detail_due_date d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.due_date >= #{searchDueDate}
				)


				AND EXISTS (
					SELECT 1 FROM sc_detail_due_date d
					WHERE d.search_condition_no = sc.search_condition_no
					AND d.due_date <= #{searchDueDate}
				)


